<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { staffApi as api, type KnowledgeSource } from '../../features/live/api';
import type { Category } from '../../features/live/knowledgeTypes';
import PreviewSelect from '../../features/preview/components/PreviewSelect.vue';
const query=ref(''),category=ref(''),categories=ref<Category[]>([]),results=ref<KnowledgeSource[]|null>(null),busy=ref(false),error=ref(''),traceId=ref('');
const settings=ref<{min_score:number;final_top_k:number}|null>(null);
onMounted(async()=>{try{categories.value=(await api<{items:Category[]}>('/api/admin/knowledge-categories')).items;settings.value=await api('/api/admin/settings/retrieval');}catch(e){error.value=(e as Error).message;}});
async function run(){if(busy.value||!query.value.trim())return;busy.value=true;error.value='';results.value=null;traceId.value='';
 try{const result=await api<{items:KnowledgeSource[];trace_id:string;settings:{min_score:number;final_top_k:number}}>('/api/admin/recall-tests',{query:query.value,category_id:category.value?Number(category.value):null});results.value=result.items;traceId.value=result.trace_id;settings.value=result.settings;}
 catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
</script>
<template><div class="pv-page live-page"><div class="live-page-heading"><div><h1>召回测试</h1><p>使用本店当前有效的知识检索，不发送客户消息，也不计入会话用量。</p></div></div><section class="pv-card live-recall-form"><form @submit.prevent="run"><label>测试问题<textarea v-model="query" aria-label="测试问题" rows="4" maxlength="2000" required placeholder="输入一条客户可能提出的问题…" :disabled="busy"/></label><div class="pv-filters"><PreviewSelect v-model="category" aria-label="测试知识库" :disabled="busy"><option value="">全部知识库</option><option v-for="c in categories" :key="c.id" :value="String(c.id)">{{c.name}}</option></PreviewSelect><span class="live-muted">Top K {{settings?.final_top_k||'—'}} · Score {{settings?.min_score??'—'}}</span><button class="wb-btn primary" :disabled="busy||!query.trim()">{{busy?'正在检索与重排…':'开始测试'}}</button></div></form></section><p v-if="error" class="live-error" role="alert">{{error}}</p><section v-if="results!==null" class="pv-card live-recall-results"><div class="pv-panel-heading"><h3>检索结果 · {{results.length}} 个片段</h3><a v-if="traceId" class="wb-text-button" :href="`?mode=live#traces/${traceId}`">查看调用记录 →</a></div><div v-if="!results.length" class="pv-empty"><strong>没有达到阈值的有效知识</strong><span>可以补充知识、调整问题，或核对检索设置。</span></div><article v-for="(result,index) in results" :key="result.id" class="pv-chunk-card"><div><span class="pv-tag">{{index+1}}</span><strong>{{result.document_title}} · v{{result.version}}</strong><span class="pv-positive">相关度 {{result.score.toFixed(4)}}</span></div><p>{{result.content}}</p></article></section></div></template>
